-- Sólo contenido editorial confirmado. No repite altas ni modifica periodos o dinero.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES('calendarios-periodos-nomina-confirmado','Calendarios y periodos de nómina: programar, revisar y cancelar','Personal',
'Organiza un calendario mensual y sus periodos, evita fechas cruzadas, consulta filtros y Excel, edita con historial y protege cambios entre pestañas. Desactiva y reactiva el calendario, y cancela sólo la programación de febrero. No calcula nómina ni mueve dinero.',
'Administrador institucional identificado con permisos de Empleados, Datos laborales y administración salarial; además Guía de procesos para consultar. Esta guía no concede accesos. Recorrido confirmado por el propietario: consultar no requiere repetir operaciones. No modificar sueldos, el bono de Bruce, cuentas o periodos existentes para leer las instrucciones.',
'Confirmado el 22/10/2026: NOM-MENSUAL-TEST · Nómina mensual de prueba, Mensual y Activo. ENE-2027-TEST · Enero de 2027 — revisión A: 01/01/2027–31/01/2027, 31 días, pago previsto 31/01/2027, fecha opcional de incidencias 28/01/2027, Programado/Próximo al momento del ensayo. FEB-2027-TEST: 01/02/2027–28/02/2027, 28 días, pago previsto 28/02/2027, incidencias Sin definir, Cancelado/No aplica. La revisión B no se guardó.',1,DATE '2026-10-22','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo IN ('EMPLEADO_LEER','EMPLEADO_LABORAL_LEER','CONDICION_SALARIAL_ADMINISTRAR') WHERE g.slug='calendarios-periodos-nomina-confirmado';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.n,v.t,'Administración',v.m,v.i,v.e,v.r,v.p,v.u FROM guia_proceso g CROSS JOIN (VALUES
(1,'Entrar y distinguir calendario de periodo','Administración → Personal y nómina → Calendarios de nómina',
'1. Inicia sesión en el portal administrativo con una cuenta institucional autorizada, no con acceso de recuperación ni cuenta familiar o docente. 2. Entra a Administración → Personal y nómina → Calendarios de nómina; el menú abre tabla, filtros, paginación y Excel. 3. Busca NOM-MENSUAL-TEST antes de crear: el ensayo ya existe y se consulta sin repetirlo. 4. Distingue el catálogo Calendarios, que organiza una frecuencia, de Periodos de nómina, que define fechas; ninguno prepara ni paga nómina.',
'Calendario NOM-MENSUAL-TEST · Nómina mensual de prueba; frecuencia Mensual. No es el calendario escolar ni una asignación del empleado.',
'Módulos correctos identificados y recorrido consultado sin alterar datos.',
'No hay que editar a Bruce, su sueldo ni el bono habitual de 500. El ejemplo documenta un ensayo aceptado, no autoriza repetir altas en operación real.','/admin/calendarios-nomina'),
(2,'Crear calendario y distinguir Cancelar del modal','Administración → Personal y nómina → Calendarios de nómina → Nuevo calendario',
'1. Sólo para un ensayo nuevo autorizado, pulsa Nuevo calendario; captura código NOM-MENSUAL-TEST, nombre Nómina mensual de prueba y descripción Calendario de ensayo para organizar periodos, sin calcular ni pagar nómina. 2. Selecciona Mensual y deja Calendario activo marcado. 3. Pulsa Revisar calendario y Cancelar dentro del modal: cierra el resumen sin guardar ni borrar la captura. 4. Repite Revisar calendario → Confirmar y guardar y comprueba la fila Activo en verde.',
'Código único NOM-MENSUAL-TEST; Mensual; Activo. Si ya existe, consulta su detalle en vez de guardar otro.',
'Calendario registrado una sola vez, sin periodos automáticos, empleados asignados ni pagos.',
'Cancelar del formulario vuelve al listado sin guardar. Cancelar dentro del modal sólo cierra la revisión. Para repetir con autorización usa otro código, nunca borres el historial.','/admin/calendarios-nomina/nuevo'),
(3,'Filtrar calendario y conservar su consulta','Administración → Personal y nómina → Calendarios de nómina → Filtros, Ver y Exportar Excel',
'1. En el listado enfoca Calendario sin escribir: aparecen hasta diez registros; escribe NOM desde tres caracteres y selecciona NOM-MENSUAL-TEST de las sugerencias. 2. Elige Estado Activos y Frecuencia Mensual, deja Texto adicional vacío y pulsa Aplicar filtros. 3. Pulsa Ver →, revisa Resumen, Historial y Gestión y vuelve con Volver al listado: conserva los filtros y la página. 4. Pulsa Exportar Excel con esa selección y comprueba únicamente el calendario filtrado.',
'Ayuda inicial hasta diez opciones; con menos registros se muestran los existentes. Escribir texto no sustituye seleccionar una sugerencia por ID.',
'Pantalla y Excel coinciden; consultar el detalle no pierde el contexto.',
'La × quita sólo la selección y Limpiar restablece criterios. Si una fila no aparece, revisa filtros antes de intentar crearla de nuevo.','/admin/calendarios-nomina'),
(4,'Registrar enero y entender la fecha opcional','Administración → Personal y nómina → Periodos de nómina → Nuevo periodo',
'1. Entra a Administración → Personal y nómina → Periodos de nómina → Nuevo periodo; selecciona Calendario activo NOM-MENSUAL-TEST y espera Frecuencia Mensual. 2. Captura código ENE-2027-TEST, nombre Enero de 2027 de prueba, inicio 01/01/2027, fin 31/01/2027, pago previsto 31/01/2027 y motivo Programación mensual de prueba de enero; todavía sin preparar ni pagar nómina. 3. Configuración avanzada es opcional: el ensayo de enero conservó 28/01/2027 en Fecha límite para recibir incidencias de nómina; si un nuevo caso no la necesita, puede dejarse vacía. 4. Pulsa Revisar periodo, prueba Cancelar dentro del modal y luego revisa de nuevo y Confirmar y guardar; comprueba Programado, 31 días y sus fechas en Resumen e Historial.',
'Inicio/fin incluyen ambos días. Pago previsto no ejecuta pagos. Incidencias son reportes de faltas, bonos o descuentos que podrían afectar el pago, no cambios de datos personales. Fecha opcional sólo de referencia.',
'Enero programado con cobertura de 31 días; fecha de incidencias 28/01/2027 conservada en el caso confirmado.',
'No repetir enero ya guardado ni borrar su fecha para que coincida con una captura vacía. La sección avanzada se abre si tiene fecha o error; no bloquea capturas ni aplica incidencias automáticamente.','/admin/periodos-nomina/nuevo'),
(5,'Rechazar un periodo con fechas cruzadas','Administración → Personal y nómina → Periodos de nómina → Nuevo periodo',
'1. Sólo en ensayo autorizado, abre Nuevo periodo y selecciona el mismo calendario NOM-MENSUAL-TEST. 2. Captura TRASLAPE-2027-TEST, nombre Periodo que no debe registrarse, inicio 15/01/2027, fin 14/02/2027, pago previsto 14/02/2027, fecha de incidencias vacía y motivo Prueba de bloqueo de fechas ya cubiertas por enero. 3. Pulsa Revisar periodo → Confirmar y guardar: debe rechazarlo porque coincide con enero, sin crear el registro ni perder la captura. 4. Pulsa Cancelar fuera del modal para volver al listado; comprueba que enero permanece y no existe ese periodo cruzado.',
'Enero cubre 01/01/2027–31/01/2027. Otro periodo del mismo calendario no puede empezar el 31/01/2027, pero sí el 01/02/2027.',
'Traslape rechazado, sin duplicar fechas ni modificar el periodo original.',
'Fin no puede ser anterior al inicio; pago tampoco puede ser anterior al inicio. Si defines incidencias, su fecha debe estar entre inicio y pago. No se presupone prorrateo ni se calculan sueldos por la duración.','/admin/periodos-nomina/nuevo'),
(6,'Registrar febrero sin fecha de incidencias','Administración → Personal y nómina → Periodos de nómina → Nuevo periodo',
'1. Entra a Periodos de nómina → Nuevo periodo y selecciona NOM-MENSUAL-TEST. 2. Captura FEB-2027-TEST, nombre Febrero de 2027 de prueba, inicio 01/02/2027, fin 28/02/2027 y pago previsto 28/02/2027. 3. Deja Configuración avanzada sin fecha y captura motivo Programación mensual de prueba de febrero. 4. Pulsa Revisar periodo → Confirmar y guardar y comprueba Programado, 28 días y Fecha límite para recibir incidencias de nómina: Sin definir.',
'Febrero comienza el día posterior al fin de enero y no se cruza. La captura principal exige inicio, fin y pago, no la fecha opcional.',
'Febrero registrado sin incidencias y sin conflicto. Su cancelación final se realiza en otro paso.',
'Si consultas el cierre ya confirmado, febrero estará Cancelado: es correcto; no lo recrees para volver al estado intermedio. Programado no significa calculado o pagado.','/admin/periodos-nomina/nuevo'),
(7,'Buscar por rango y comprobar Excel y retorno','Administración → Personal y nómina → Periodos de nómina → Filtros → Exportar Excel',
'1. En Periodos de nómina selecciona Calendario NOM-MENSUAL-TEST, deja Periodo y Texto adicional vacíos, elige Estado Programados, Frecuencia histórica Mensual y rango 01/01/2027–31/01/2027; pulsa Aplicar filtros. 2. Comprueba sólo enero y exporta Excel: una fila de datos, 31 días, inicio 01/01/2027 y fin 31/01/2027. 3. Pulsa Ver de enero y Volver al listado: deben conservarse calendario, estado, frecuencia, rango y página. 4. Antes de cancelar febrero, cambia rango a 31/01/2027–01/02/2027 y aplica: aparecen enero y febrero; después del cierre usa Estado Todos para consultar ambos.',
'El rango busca periodos que coincidan con cualquier fecha incluida, no sólo extremos idénticos. La ayuda independiente Periodo permite seleccionar uno por ID.',
'Filtros y Excel confirmados; retorno conserva criterios. Enero/febrero coinciden con el rango entre el último y el primer día.',
'Si mantienes Estado Programados tras cancelar febrero, sólo aparecerá enero; no es pérdida de datos. Excel respeta los mismos filtros y muestra Sin definir cuando la fecha opcional está vacía.','/admin/periodos-nomina'),
(8,'Editar enero sin cambiar su calendario histórico','Administración → Personal y nómina → Periodos de nómina → Editar → Resumen e Historial',
'1. En el listado localiza ENE-2027-TEST y pulsa Editar; el calendario histórico no puede reasignarse y el motivo del cambio comienza vacío. 2. Cambia sólo Nombre a Enero de 2027 revisado de prueba, conserva las fechas y captura motivo Se aclara el nombre del periodo de prueba sin cambiar su cobertura. 3. Pulsa Revisar cambios → Confirmar y guardar; debe permitir editar sin detectar conflicto con el mismo registro. 4. En Resumen comprueba 31 días, fechas conservadas, motivo original y Última gestión; en Historial consulta alta y modificación con fecha y usuario.',
'El caso conserva fecha opcional 28/01/2027. Modificar el nombre no altera cobertura ni vuelve a registrar enero.',
'Edición guardada con historial, sin sobrescribir el motivo original ni cambiar el calendario histórico.',
'Si necesitas otro calendario, no lo reasignes silenciosamente: revisa cancelación y un registro nuevo autorizado. No repetir el cambio si sólo consultas la guía.','/admin/periodos-nomina'),
(9,'Impedir que otra pestaña sobrescriba enero','Administración → Personal y nómina → Periodos de nómina → Editar en dos pestañas',
'1. Antes de guardar en cualquiera, abre Editar de ENE-2027-TEST en dos pestañas A y B. 2. En A escribe Nombre Enero de 2027 — revisión A, motivo Prueba de protección entre pestañas, cambio A., y pulsa Revisar cambios → Confirmar y guardar. 3. Sin recargar B, escribe Nombre Enero de 2027 — revisión B, motivo Prueba de protección entre pestañas, cambio B., e intenta guardar confirmando. 4. Comprueba aviso de cambio en otra pestaña y consulta enero desde el listado: conserva revisión A, la revisión B no aparece como guardada en el historial.',
'Nombre final confirmado: Enero de 2027 — revisión A. La pantalla B conserva una versión anterior y no puede sobrescribir A.',
'Conflicto detectado sin escritura adicional desde la segunda pestaña.',
'Recarga y revisa los cambios vigentes antes de un nuevo intento; no reenvíes una pantalla atrasada ni interpretes el aviso como una cancelación del periodo.','/admin/periodos-nomina'),
(10,'Desactivar y reactivar sin cancelar periodos','Administración → Personal y nómina → Calendarios de nómina → Editar',
'1. Localiza NOM-MENSUAL-TEST, pulsa Editar y comprueba que Mensual está protegida porque ya tiene periodos; desmarca Calendario activo y confirma Revisar cambios → Confirmar y guardar. 2. Entra a Periodos de nómina → Nuevo periodo y busca el calendario: ya no debe aparecer como activo; no guardes otro periodo. 3. Consulta el listado de Periodos de nómina y verifica que enero/febrero siguen existiendo; desactivar calendario no los cancela. 4. Regresa a Calendarios de nómina, pulsa Limpiar, filtra Inactivos, edita el calendario, marca Calendario activo y confirma para dejarlo Activo.',
'Frecuencia protegida incluso si luego se cancelan periodos. Calendario inactivo sigue disponible en filtros históricos; no permite nuevas altas o ediciones de periodos hasta reactivarlo.',
'Calendario reactivado, periodos conservados y sin generación automática.',
'Para otra frecuencia crea otro calendario. Cambiar nombre o descripción no reescribe los datos históricos copiados en periodos. No modificar la base de datos para saltar la protección.','/admin/calendarios-nomina'),
(11,'Cancelar febrero con motivo y confirmación','Administración → Personal y nómina → Periodos de nómina → Ver febrero → Gestión',
'1. Abre Periodos de nómina, limpia filtros, busca FEB-2027-TEST y pulsa Ver → Gestión. 2. En Cancelar este periodo captura Se cancela únicamente la programación de febrero de prueba; no existe nómina ni pago asociado. y pulsa Revisar cancelación. 3. Revisa periodo, calendario, fechas y motivo; pulsa primero Cancelar dentro del modal y comprueba que febrero sigue Programado. 4. Repite Revisar cancelación y pulsa Confirmar cancelación; debe quedar Cancelado, sólo consulta, con motivo e historial.',
'Cancelar del modal no ejecuta la operación; Confirmar cancelación cancela únicamente la programación de febrero.',
'Febrero cancelado sin borrar, sin editar/reactivar y sin afectar enero ni dinero.',
'Un cancelado libera fechas, no su código. Si realmente se requiere un reemplazo autorizado, usa otro código y comprueba fechas; no hacerlo sólo para leer esta guía. No cancela pagos ni elimina el calendario.','/admin/periodos-nomina'),
(12,'Comprobar cierre y continuar sin repetir el ensayo','Administración → Personal y nómina → Periodos de nómina → Filtros → Ver → Historial',
'1. Selecciona NOM-MENSUAL-TEST, Estado Todos y limpia fechas o selección de Periodo que oculten filas. 2. Comprueba enero con nombre Enero de 2027 — revisión A, 31 días, pago 31/01/2027, incidencias 28/01/2027 y Programado; febrero con 28 días, pago 28/02/2027, incidencias Sin definir y Cancelado. 3. Filtra Programados para ver enero y Cancelados para ver febrero, y consulta el motivo en Historial; calendario queda Activo. 4. Conserva este cierre confirmado y revisa con el administrador el siguiente análisis de preparación de nómina: elegibilidad por vigencias, sueldos/conceptos y periodos parciales, antes de implementar cálculos.',
'Enero Programado/Próximo durante el ensayo de octubre de 2026. Febrero Cancelado/No aplica. No se guardó TRASLAPE-2027-TEST ni la revisión B.',
'Recorrido principal confirmado el 22/10/2026, documentado sin repetir registros ni modificar cuentas, empleados o sueldo base.',
'Próximo cambia por fecha institucional a En curso o Transcurrido, no a pagado. La aceptación no equivale a una auditoría exhaustiva. Preparación, incidencias reales, impuestos, préstamos y pagos requieren acuerdo posterior; no asumir prorrateo automático.','/admin/periodos-nomina')
)v(n,t,m,i,e,r,p,u) WHERE g.slug='calendarios-periodos-nomina-confirmado';

UPDATE guia_proceso_paso SET instrucciones='1. En Conceptos por empleado filtra Bruce y BON-PUNT-TEST con Estado Todas y sin fechas que oculten registros. 2. Comprueba el cierre confirmado:500 MXN desde 01/01/2027 sin fin, Próxima al momento del ensayo;600 desde 01/02/2027 sin fin, Cancelada. 3. En Ver → Historial consulta cancelación y restauración sin repetir operaciones ni alterar el bono de 500. 4. Consulta Guía de procesos → Personal → Calendarios y periodos de nómina: programar, revisar y cancelar; ese recorrido también está confirmado. Después se analiza preparación de nómina, todavía sin calcular ni pagar.',precaucion='El recorrido de conceptos ya está confirmado y también el siguiente: consulta Guía de procesos → Personal → Calendarios y periodos de nómina: programar, revisar y cancelar. No repetir asignaciones ni modificar el bono de 500 o sueldos. Después se analiza preparación de nómina y revisión explícita de parciales; todavía no se calculan ni ejecutan pagos.'
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='conceptos-por-empleado-bono-confirmado') AND numero=10;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-22' WHERE slug='conceptos-por-empleado-bono-confirmado';
